INSERT INTO events (id, title, tagline, category, department, club_name, venue_id, venue_name, start_date, end_date, registration_deadline, capacity, registered_count, team_type, entry_fee, prize_pool, description, rules, schedule, image_url, status, coordinator_name, coordinator_phone, coordinator_email, faculty_advisor) VALUES
('EVT-2026-001', 'Abhiyaan 2026: 24-Hour National Hackathon', 'Build the Next Generation of AI & Web Innovations', 'Technical', 'Computer Science & Engineering', 'Coding & Innovation Club', 'v1', 'SAC Main Auditorium & Labs', '2026-11-18 09:00:00', '2026-11-19 10:00:00', '2026-11-16 23:59:00', 300, 184, 'Team (2-4 Members)', 'Free', '₹50,000 Cash + Cloud Credits', 'The flagship hackathon of RGUKT IIIT RK Valley. Build web, mobile and AI applications solving regional agricultural, educational, and healthcare problems.', '["Valid RGUKT ID mandatory","Build during 24h hackathon period","Open-source code submission on GitHub"]', '[{"time":"Day 1 - 09:00 AM","activity":"Opening Keynote"},{"time":"Day 1 - 10:00 AM","activity":"Problem Statements Released"},{"time":"Day 2 - 09:00 AM","activity":"Final Project Demos"}]', 'https://images.unsplash.com/photo-1504384308090-c894fdcc538d?w=800', 'approved', 'B. Tejaswi (CSE E4)', '+91 98480 12345', 'tejaswi.coord@rguktrkv.ac.in', 'Dr. Suresh Kumar (HOD CSE)'),
('EVT-2026-002', 'Sanskriti 2026: Cultural Fiesta & Battle of Bands', 'Rhythm, Drama & Soulful Harmonies under the Stars', 'Cultural', 'All Branches', 'Cultural Arts Society', 'v2', 'Open Air Theatre (OAT)', '2026-11-21 17:30:00', '2026-11-21 23:00:00', '2026-11-19 18:00:00', 4000, 1420, 'Solo & Group', 'Free', 'Trophies + ₹25,000', 'Experience electrifying musical concerts, Indian folk & western dance showdowns, and theatrical drama in the Open Air Theatre.', '["Audio tracks submitted 24h prior","Group dance limit 6 mins","Band limit 15 mins"]', '[{"time":"05:30 PM","activity":"Invocation & Classical Series"},{"time":"07:30 PM","activity":"Battle of the Bands"},{"time":"10:00 PM","activity":"Star Night"}]', 'https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?w=800', 'approved', 'M. Sai Krishna (ECE E4)', '+91 97000 54321', 'cultural.lead@rguktrkv.ac.in', 'Dr. Padmaja (Faculty Incharge)'),
('EVT-2026-003', 'RGUKT Premier League (RPL) 2026', 'Inter-Departmental T20 Cricket Tournament', 'Sports', 'Physical Education Dept', 'Sports Council', 'v6', 'Main University Sports Ground', '2026-11-25 08:00:00', '2026-11-28 18:00:00', '2026-11-22 20:00:00', 3000, 420, 'Department Team', 'Free', 'RPL Trophy + Gold Medals', '8 engineering departments compete in 10-over league matches under floodlights.', '["Department official team only","Uniform jerseys required","ICC T20 rules applied"]', '[{"time":"Day 1 - 08:00 AM","activity":"CSE vs ECE"},{"time":"Day 2 - 02:00 PM","activity":"Quarter Finals"},{"time":"Day 4 - 05:00 PM","activity":"Grand Finale"}]', 'https://images.unsplash.com/photo-1540747913346-19e32dc3e97e?w=800', 'approved', 'P. Divya Reddy (Mech E4)', '+91 99887 76655', 'sports.sec@rguktrkv.ac.in', 'Mr. Ramesh (Physical Director)'),
('EVT-2026-004', 'Cybersurge: Capture The Flag (CTF) Arena', 'Reverse Engineering & Ethical Hacking Challenge', 'Technical', 'Computer Science & Engineering', 'Cybersecurity Student Club', 'v3', 'SAC Computer Labs (Lab 1)', '2026-11-20 14:00:00', '2026-11-20 20:00:00', '2026-11-19 23:59:00', 120, 92, 'Solo or Duo (1-2)', 'Free', '₹15,000 Cash + Certificates', 'Competitive jeopardy-style cybersecurity challenges covering web exploitation, forensics, cryptography, and binary analysis.', '["No attacks on contest infrastructure","Individual VPN access required","No sharing flags between teams"]', '[{"time":"02:00 PM","activity":"VPN Access Briefing"},{"time":"02:30 PM","activity":"Flags Open"},{"time":"07:30 PM","activity":"Scoring Closes"}]', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?w=800', 'approved', 'K. Vamsi (CSE E3)', '+91 98490 22334', 'vamsi.ctf@rguktrkv.ac.in', 'Dr. K. Srinivas Rao'),
('EVT-2026-005', 'Generative AI & LLM Systems Masterclass', 'Building Autonomous AI Workflows with Gemini & Python', 'Workshops', 'Computer Science & Engineering', 'AI/ML Developers Club', 'v4', 'CSE Department Seminar Hall', '2026-11-22 10:00:00', '2026-11-22 16:30:00', '2026-11-21 18:00:00', 150, 145, 'Individual', 'Free', 'Verified E-Certificate', 'Hands-on architectural deep dive into RAG pipelines, autonomous agents, and embedding models with code labs.', '["Bring personal laptops with Python installed","Attendance required for certification"]', '[{"time":"10:00 AM","activity":"Session 1: LLM Foundations"},{"time":"02:00 PM","activity":"Session 2: Agent Tools & RAG"}]', 'https://images.unsplash.com/photo-1618005182384-a83a8bd57fbe?w=800', 'approved', 'A. Harshavardhan (CSE E3)', '+91 91234 55667', 'harsha.ai@rguktrkv.ac.in', 'Dr. B. Prasad Rao');
